    const n = big ? 20000 : r.int(1, 9);
    const label = r.shuffle(Array.from({ length: n }, (_, i) => i));
    const edges = [];
    // half the time a long thin tree, so the centre is far from every leaf
    const thin = r.bool(0.5);
    for (let i = 1; i < n; i++) {
      const p = thin ? r.int(Math.max(0, i - 3), i - 1) : r.int(0, i - 1);
      edges.push(r.bool() ? [label[i], label[p]] : [label[p], label[i]]);
    }
    return [n, r.shuffle(edges)];
  }

