function shortestTreeRoots(n: number, edges: number[][]): number[] {
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const height = (root: number): number => {
    const dist = new Array(n).fill(-1);
    dist[root] = 0;
    const queue = [root];
    let far = 0;
    for (let i = 0; i < queue.length; i++) {
      const u = queue[i];
      far = Math.max(far, dist[u]);
      for (const v of adj[u]) if (dist[v] < 0) { dist[v] = dist[u] + 1; queue.push(v); }
    }
    return far;
  };
  const h = Array.from({ length: n }, (_, i) => height(i));
  const best = Math.min(...h);
  return h.flatMap((x, i) => (x === best ? [i] : []));
}

