function shortestTreeRoots(n: number, edges: number[][]): number[] {
  if (n <= 2) return Array.from({ length: n }, (_, i) => i);
  const adj: number[][] = Array.from({ length: n }, () => []);
  const deg = new Array(n).fill(0);
  for (const [a, b] of edges) {
    adj[a].push(b); adj[b].push(a);
    deg[a]++; deg[b]++;
  }
  let layer: number[] = [];
  for (let i = 0; i < n; i++) if (deg[i] === 1) layer.push(i);
  let remaining = n;
  while (remaining > 2) {
    remaining -= layer.length;
    const next: number[] = [];
    for (const leaf of layer) {
      for (const v of adj[leaf]) {
        if (--deg[v] === 1) next.push(v);
      }
    }
    layer = next;
  }
  return layer;
}

